  0, 3, 2,  0, 2, 1,   // -z
  1, 2, 6,  1, 6, 5,   // +x
  0, 4, 7,  0, 7, 3,   // -x
  3, 7, 6,  3, 6, 2,   // +y
  0, 1, 5,  0, 5, 4,   // -y
