function buildCube() {
  const positions = [];
  for (const v of CUBE_VERTICES) positions.push(v[0], v[1], v[2]);
  return {
    positions,
    indices: CUBE_INDICES.slice(),
    vertexCount: CUBE_VERTICES.length,
    faceCount: CUBE_INDICES.length / 3,
  };
}

function getVertex(positions, i) {
  return [positions[3 * i], positions[3 * i + 1], positions[3 * i + 2]];
}
function sub(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function cross(a, b) {
  return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
}
function dot(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }

// A point strictly inside the mesh (average of the unique referenced vertices).
function interiorPoint(positions, indices) {
  const seen = new Set();
  let n = 0, x = 0, y = 0, z = 0;
  const count = indices ? indices.length : positions.length / 3;
  for (let k = 0; k < count; k++) {
    const i = indices ? indices[k] : k;
    if (seen.has(i)) continue;
    seen.add(i);
    x += positions[3 * i]; y += positions[3 * i + 1]; z += positions[3 * i + 2];
    n++;
  }
  return n === 0 ? [0, 0, 0] : [x / n, y / n, z / n];
}

// Per-face orientation test: signed volume of tetra (interiorPoint, a, b, c).
// Positive => the triangle's winding faces away from the interior (outward).
function audit(geometry) {
  const positions = geometry.positions || geometry.vertices;
  const indices = geometry.indices || null;
  const faces = Math.floor((indices ? indices.length : positions.length) / 3);
  const p = interiorPoint(positions, indices);

  let inwardFaces = 0;
  for (let f = 0; f < faces; f++) {
    const ia = indices ? indices[3 * f] : 3 * f;
    const ib = indices ? indices[3 * f + 1] : 3 * f + 1;
    const ic = indices ? indices[3 * f + 2] : 3 * f + 2;
    const a = sub(getVertex(positions, ia), p);
    const b = sub(getVertex(positions, ib), p);
    const c = sub(getVertex(positions, ic), p);
    const vol = dot(a, cross(b, c)) / 6;
    if (vol < 0) inwardFaces++;
  }

  return {
    faces,
    inwardFaces,
    facesOutwardRatio: faces === 0 ? 0 : (faces - inwardFaces) / faces,
  };
}

function main() {
  const result = audit(buildCube());
  console.log(JSON.stringify(result));
  return result;
}

module.exports = { audit, buildCube, main };

