const fs = require('fs');
function parseCsv(text){
  const rows=[];let row=[];let i=0;
  while(i<text.length){
    let raw='';
    if(text[i]==='"'){
      raw='"';i++;
      while(i<text.length){
        if(text[i]==='"'){
          if(text[i+1]==='"'){raw+='""';i+=2;}else{raw+='"';i++;break;}
        }else{raw+=text[i];i++;}
      }
    }else{
      while(i<text.length&&text[i]!==','&&text[i]!=='\n'&&text[i]!=='\r'){raw+=text[i];i++;}
    }
    row.push(raw);
    if(i>=text.length){rows.push(row);row=[];break;}
    if(text[i]===','){i++;continue;}
    if(text[i]==='\r'){i++;}
    if(i<text.length&&text[i]==='\n'){i++;rows.push(row);row=[];continue;}
  }
  if(row.length)rows.push(row);
