function unquote(raw){
  if(raw.length>=2&&raw[0]==='"'&&raw[raw.length-1]==='"')return raw.slice(1,-1).split('""').join('"');
  return raw;
}
function requote(raw,val){
  if(raw.length>=2&&raw[0]==='"')return '"'+val.split('"').join('""')+'"';
  if(/[",\n\r]/.test(val))return '"'+val.split('"').join('""')+'"';
