const N = 300000, K = 10;
const t0 = process.hrtime.bigint();
const h = [];
function push(v){ h.push(v); let i = h.length - 1; while (i > 0){ const p = (i - 1) >> 1; if (h[p] <= h[i]) break; const t = h[p]; h[p] = h[i]; h[i] = t; i = p; } }
function replaceRoot(v){ h[0] = v; const n = h.length; let i = 0; for(;;){ const l = 2*i+1, r = l+1; let m = i; if (l < n && h[l] < h[m]) m = l; if (r < n && h[r] < h[m]) m = r; if (m === i) break; const t = h[m]; h[m] = h[i]; h[i] = t; i = m; } }
let x = 42;
for (let i = 0; i < N; i++){
  x = (Math.imul(x, 1103515245) + 12345) & 0x7fffffff;
  if (h.length < K) push(x);
  else if (x > h[0]) replaceRoot(x);
}
const ms = Number(process.hrtime.bigint() - t0) / 1e6;
